data.query:
query employee($where:EmployeeWhereInput){
  employee (where:$where) {
    edges {
      node {
        id
      }
    }
  }
}

query productionSetup($wherePS: ProductionSetupWhereInput, $whereO: ProductionSetupOperatorWhereInput){
  productionSetup (where: $wherePS) {
    edges {
      node {
        id
        operators {
          edges {
            node {
              id
              employeeId
            }
          }
        }
      }
    }
  }
  productionSetupOperator(where:$whereO) {
    edges {
      node {
        id
        workcenter {id code}
        productionSetupId
      }
    }
  }
}

query Query($where: ProductionSetupBOMWhereInput, $orderBy: [ProductionSetupBOMOrderByInput!], $first: Int, $after: String) {
  bom:productionSetupBOM(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    total
    edges {
      node {
        id
        consumptionMode {
          name
          actualUsage
        }
      }
    }
  }
}

query Query(
  $whereP: ProductionSetupOutputWhereInput, 
  $whereQ:QualitySpecificationGroupWhereInput,
  $whereI: InventoryWhereInput,
  $whereS: QualitySubjectListWhereInput
) {
  productionSetupOutput(where: $whereP, first:1) {
    edges {
      node {
        id
        productId
        productionSetup {
          operators {
            edges {
              node {
                employeeId
              }
            }
          }
        }
        workcenterId
        productStrategyProcess {
          id processId code
        }
        workOrderId
        workOrderProcess {
          id processId code
        }
      }
    }
  }
  qualitySpecificationGroup(where:$whereQ, first:1) {
    edges{
      node {
        id
        name
        subjects(where:$whereS) {
          edges {
            node {
              id
            }
          }
        }
        specifications {
          edges {
            node {
              id
              specification {
                id
                expectedValue
                type {
                  quantity
                  quality
                  attribute
                }
                expectedValue
                lowerBound
                upperBound

              }
            }
          }
        }
      }
    }
  }
  inventory(where:$whereI){
    edges {
      node {
        number
        id
        lotId
        locationId
        inventoryStatusId
        productId
        productStrategyProcessId
        workOrderProcessId
        masterInventoryId
        quantity {value unitId}
      }
    }
  }
}

data.transform:
(

  $R := $state.context.REQUEST.DATA;
  $L := $state.context.LOCAL;
  $rid := $cuid();
  $checks := $L.group.specifications.edges.node.specification.(
    $id := id;
    $r := $lookup($R.results, $id);

    $pass :=  type.attribute ? (
      $r.value
    ) : type.quality ? (
       $r.value = expectedValue
    ) : (
      $isNilOrEmpty(lowerBound) ? (
        expectedValue = $r.value
      ) : (
        $parseNumber($r.value) >= lowerBound
        and
        $parseNumber($r.value) <= upperBound
      )
    );

    {
      "qualitySpecificationId": $id,
      "result": $pass,
      "value": $string($r.value),
      "note": $r.note,
      "complete":true,
      "reportId":$rid
    }
  );
  $report := {
    "id": $rid,
    "code": $moment().format("YY.MM.DD") & ":" &  $L.output.productStrategyProcess.code,
    "result": $not(false in [$checks.result]),
    "complete": true,
    "date": $now(),
    "qualitySpecificationGroupId": $L.group.id,
    "employeeId": $L.output.productionSetup.operators.edges[0].node.employeeId,
    "inventoryId": $R.inventoryId,
    "processId": $L.output.workOrderProcess.processId,
    "productId": $L.output.productId,
    "productStrategyProcessId":$L.output.productStrategyProcess.id,
    "subjectId":$L.group.subjects.edges[0].node.id,
    "workOrderId": $L.output.workOrderId,
    "workOrderProcessId": $L.output.workOrderProcess.id,
    "workcenterId": $L.output.workcenterId
  };
  {
    "payloadR": {
      "create": $report
    },
    "payloadC": $checks.{
      "create": $
    }
  }

)

