        workOrderProcessId


        inventoryStatus {
          id
          name
          active
          suspect
          containment
          productionLoaded
          splitPrevent
        }
        quantity {
          value
          unitId
        }
        weightUnitId
        grossWeight
        netWeight
        tareWeight
        theoreticalWeight
        masterInventory {
          id
          number
          masterInventoryStatus {
            id
            name
            active
            containment
          }
        }
      }
    }
  }
}

