mutation createUpdateInventory(
  $payloadI:[InventoryUpdatePayloadInput!]!,
  $payloadC:[InventoryCreatePayloadInput!]!
){
  uinv:updateInventory(payload:$payloadI){
    id
    number
  }
  cinv:createInventory(payload:$payloadC){
    id
}
}

data.variablesTransform:
(
  $R := $state.context.REQUEST.DATA;
  $L := $state.context.LOCAL;
  $inv := $L.inventory;

  {
    "payloadT": cinv.(
      $id := id;
      {
        "create": $inv.{
          "sourceQuantity": {
             "value": $R.qty,
            "unitId": quantity.unitId
          },
          "destinationQuantity": {
            "value": $R.qty,
            "unitId": quantity.unitId
          },
          "sourceInventoryId":id,
          "customData": $state.context.CLAIMS ? $state.context.CLAIMS : $state.claims,
          "destinationInventoryId":$id,
          "sourceLocationId": locationId,
          "destinationLocationId": locationId,
          "sourceInventoryStatusId": inventoryStatus.id,
          "destinationInventoryStatusId": "Scrap",
          "sourceLotId": lotId,
          "destinationLotId": lotId,
          "sourceProductId":productId,
          "destinationProductId":productId,
          "sourceProductStrategyProcessId":productStrategyProcessId,
          "destinationProductStrategyProcessId":productStrategyProcessId,
          "sourceWorkOrderProcessId": workOrderProcessId,
          "destinationWorkOrderProcessId": workOrderProcessId,
          "sourceMasterInventoryId":masterInventory.id,
    /*       "destinationMasterInventoryId":masterInventory.id, */
          "statusId":$coalesce([$state.context.REQUEST.DATA.statusId,$state.context.DEFAULT.statusId, "Review"]),
          "adjustmentCodeId": $coalesce([$state.context.REQUEST.DATA.adjustmentCodeId,$state.context.DEFAULT.adjustmentCodeId, "Manual"]),
          "transactionTypeId": "Inventory Status Change"
        }
      }
    )
  }

)

